const rows = $input.all();
function segs(n) { return String(n || '').split('::'); }
function readName(n) {
  if (typeof n === 'string') { return n; }
  return (n && (n.web || n.other || n.ios || n.android)) || '';
}
function screenTag(title) {
  let t = String(title || '').replace(/^[DM]\s*-\s*/, '').replace(/^Email\s*-\s*/i, 'email_');
  t = t.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
