  const pi = rows[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const m = (src[idx] || src[i] || {}).json || {};
  const base = { projectId: m.projectId, projectName: m.projectName || '', keyId: m.keyId, keyName: m.keyName, reason: m.reason || '', screenshotCount: m.screenshotCount, siblingIdCount: m.siblingIdCount };
